import{_ as t,a as r}from"./chunks/2c7de49dd74ff1713b64.nbQnvP_X.js";import{_ as l,C as i,o,c as n,j as e,a as s,E as h,a6 as u}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"2025年，聪明的创作者将如何建立受众","description":"","frontmatter":{"title":"2025年，聪明的创作者将如何建立受众","originalTitle":"How Smart Creators Will Build An Audience In 2025","date":"2024-10-12","originalUrl":"https://thedankoe.com/letters/the-future-of-creators-how-to-build-an-audience-in-2025/","minutes":14,"sourceHash":"fb6bcaf3b1ea3c8ce5f8df04cc6d1c90b7e0387a307decb6ec8f045aef4d13ad","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-of-creators-how-to-build-an-audience-in-2025/"}]]},"headers":[],"relativePath":"letters/the-future-of-creators-how-to-build-an-audience-in-2025.md","filePath":"letters/the-future-of-creators-how-to-build-an-audience-in-2025.md"}'),d={name:"letters/the-future-of-creators-how-to-build-an-audience-in-2025.md"};function c(m,p,b,f,_,k){const a=i("ArticleMeta");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"_2025年-聪明的创作者将如何建立受众",tabindex:"-1"},[s("2025年，聪明的创作者将如何建立受众 "),e("a",{class:"header-anchor",href:"#_2025年-聪明的创作者将如何建立受众","aria-label":'Permalink to "2025年，聪明的创作者将如何建立受众"'},"​")],-1)),h(a),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/vNObjIoMe_w?si=PKzwHfx26hLfSY34" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我开始在社交媒体上写作，是因为我想做我自己想做的事。</p><p>但写作并不是我第一次尝试获得自由的方式。</p><p>在那之前，我完全没有意识到，写作——这项对英语专业学生和实体书作者来说很奇怪的技能——竟是我掌控自己人生的门票。</p><p>我的第一份“正经工作”是在一家零售商营销能动性公司做网页设计师（想象一下家具和家电零售商的电商网站）。</p><p>那是在我兼职打印店、和另外7个哥们一起住在兄弟会宿舍里勉强付房租之后的事。住在那里的时候，我用尽一切办法想为自己工作。我一直想做点有创意的事。我什么都试过：摄影、数字艺术、代发货、多个电商网站、创办一个自动化能动性公司、自由网页开发，等等。全都失败了。</p><p>但我们都知道，失败是件好事。</p><p>我拿到那份网页设计工作时，已经上了5年大学，债务开始堆积。我记得自己至少换了4次专业，剩下大约一年就毕业了。</p><p>但我的梦想没有死。我知道，一旦我接受了这份工作，倒计时就开始朝着我的毁灭滴答作响。</p><p>找一份工作，是我存在的祸根。是我“反愿景”的核心。</p><p>我知道我会变得舒适安逸。</p><p>我知道如果我现在不采取行动，我这一辈子都会困在企业体制里。</p><p>而随着责任越堆越多，脱身只会越来越难。</p><p>幸运的是，我身上积累了太多失败经验，靠自由职业网页设计赚了一笔不小的钱，足以辞掉工作。我在工作中大部分时间都在拖延本职任务，去追求和学习自由职业。我是个糟糕的员工，但恰好做得刚好够，没被发现。</p><p>但我作为自由职业者，工作强度依然接近全职。</p><p>我依然厌恶为别人的项目工作。</p><p>就是那时，我终于转向了社交媒体。</p><h3 id="我获得自由的关键" tabindex="-1">我获得自由的关键 <a class="header-anchor" href="#我获得自由的关键" aria-label="Permalink to &quot;我获得自由的关键&quot;">​</a></h3><p>你从赞美或成功中什么都学不到。</p><p>你从负面经历和失败中学习。</p><p>正是我那些“失败”的生意，教会了我所有的技能（比如品牌塑造、设计、文案写作和分发渠道），也正是这些技能塑造了我的思维，让我最终在互联网商业发展到这个阶段时，认识到社交媒体的重要性。</p><p>2019年，在推特上刷了几个月之后，我意识到了一些事。</p><ul><li>人们其实就是……在写字。没有图片，没有设计，没有耗时的视频剪辑。就像在一个巨大的公共群聊里发消息。</li><li>人们谈论的都是我已经知道的东西。我常常想，“这条推文我也能写。”</li><li>人们把自己的主页当作吸引客户的方式。有些人就是靠网页设计做到的（“嘿，这我也能做啊。”）</li><li>这些人真的很酷。我感觉自己身处一个没有商业腔调、没有我所厌恶的“专业感”的地方，但他们照样赚得盆满钵满。</li></ul><p>那一刻，我恍然大悟。</p><p>“等等，这些人根本没有发冷邮件，也没有搞什么奇怪的获客策略。”</p><p>他们只是在建立受众。</p><p>你是说，我只需要写自己喜欢的内容，就能吸引客户主动找上我？</p><p>我为什么一直在毁掉自己的心理健康，手动发冷邮件，跟一个我厌恶的细分领域里的人合作，就因为有人说这样能赚钱？</p><p>折腾了这么久……原来写作，恰恰就是我获得自由的关键。</p><p>为什么？</p><p>第一，它能帮我拿到自由职业客户，但这仅仅是个开始。</p><p>如果我坚持下去，哪怕只积累起一小群受众，我就能做一些杠杆更高的事。</p><p>实体产品、数字产品、软件、书籍……我终于能“睡后赚钱”，不再接那些我根本不在乎的项目。</p><p>正如很多人都能看到的，凭着足够的坚持和迭代，那个愿景成真了。</p><p>但金钱只是冰山一角。</p><p>大多数人没意识到这一点。他们喜欢说，“他们做这些不就是为了钱”，但事实上，没有人在人生中做任何事只出于一个理由。</p><p>是，没错，我们是为了钱。钱是必要的。把你对金钱的那套被灌输的观念先放一边。重点是：</p><p>还有什么工作，比靠做自己就能赚钱更让人有成就感？</p><p>卖出对他人有正面影响的产品。</p><p>通过谈论那些对你来说重要的兴趣，去帮助别人。</p><p>我知道这听起来有点无私，但对我来说，这比单纯为了生存而赚钱——即便是做自由职业——听起来要好太多了。</p><p>自由职业并没有我想象中那么自由。</p><h2 id="受众建立的未来" tabindex="-1">受众建立的未来 <a class="header-anchor" href="#受众建立的未来" aria-label="Permalink to &quot;受众建立的未来&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>自那以后，社交媒体已经变了。</p><p>你可能不信，但现在建立受众，反而比以前更容易了。</p><p>当年还没有TikTok、Reels和Shorts。</p><p>当然，这些都不是以写作为主的形式，但它们的流行改变了整个算法的运作方式。</p><p>算法已经转向了一种<em>兴趣图谱（interest graph）</em>。</p><p>这意味着——<em>社交媒体粉丝数（大多数情况下）已经不再重要了</em>。</p><p>“为你推荐”页面改变了我们在信息流中看到的内容。</p><p>是的，你仍然会看到你关注的人的内容，但前提是你持续对那个账号表现出兴趣。</p><p>多数时候，你的信息流里充斥的是与你分享过、长时间观看过，或最近互动过的话题相关的帖子。</p><p>这意味着几件事：</p><ul><li>小账号如果学会写出引人入胜且相关的内容，就能相当快地增长。</li><li>要在社交媒体上保持相关性，你不能像以前那样写得太深。你必须保持相对浅显。（这不是坏事。你被迫要在人们所在的层次上与他们相遇，也就是初学者水平，然后真正改变他们的生活，直到他们能理解你的深度。）</li><li>如果你想<em>建立</em>并<em>留住</em>你的受众，邮件列表比以往任何时候都更重要。社交媒体成为了粉丝认识你的“第一层”。而不是（同样，大多数情况下）用来培养或教育他们的地方。</li></ul><p>我这里说的是短内容平台。</p><p>Instagram、X（推特）、LinkedIn、TikTok，以及各类短视频（shorts）。</p><p>长篇YouTube视频和播客的情况则稍有不同。</p><h3 id="邮件列表就是新的受众" tabindex="-1">邮件列表就是新的受众 <a class="header-anchor" href="#邮件列表就是新的受众" aria-label="Permalink to &quot;邮件列表就是新的受众&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>我已经谈论这件事有2到3年了，现在看起来，其他人也开始明白过来了。</p><p>就信任、权威和杠杆而言——长内容更重要。</p><p>就流量、爆红和注意力而言——短内容更重要。</p><p>重点是，两者都很重要。</p><p>如果你只依赖其中一种，你就限制了自己的长期成功。</p><p>是的，你可以整天在社交媒体上谈论一些浅显的话题，快速赚点钱，但你并没有在建立一个能在数年后依然存在的东西，无论是在数字资产层面，还是在人们心智占位层面。</p><p>如果你不写长内容，不仅会被人从记忆中遗忘，你的生意还可能被社交平台一瞬间掐断。</p><p>如果你不写短内容，你就无法建立受众。</p><p>如果你不写长内容，你就无法留住受众。</p><p>你的粉丝数量已经不再代表你的受众规模了，因为“为你推荐”页面的存在，让每个人都有机会爆红。</p><p>邮件列表是唯一真正能代表你受众规模的东西。</p><p>邮件列表是新的身份象征。</p><p>没有人能把你的邮件列表夺走。</p><p>我们把这些拼在一起看看。</p><h3 id="_1-写短内容来吸引人。" tabindex="-1">1）写短内容来吸引人。 <a class="header-anchor" href="#_1-写短内容来吸引人。" aria-label="Permalink to &quot;1）写短内容来吸引人。&quot;">​</a></h3><p>除非你有人可以发送邮件，否则你无法建立起一个邮件列表。</p><p>这就像有人写了本书，却指望亚马逊的自然流量让他们发财一样。</p><p>不。你需要<em>自己的流量来源，去为你的产品和写作提供动力</em>。</p><p>也就是社交媒体上的短内容。</p><p>在如今的社交媒体环境里，短内容写作是你的根基。</p><p>写出你的观点。</p><p>给出简短且可执行的建议，但不要把所有空白都填满。让人们提问，以获得更多互动。</p><p>发表一些从你的角度来看是真实的、有争议性的观点。让那些看不到两面的人自行过滤掉自己。</p><p>用最简单的话来说：</p><ul><li>选一个想法，任何想法都行。</li><li>从你自己的角度把它写下来，别在意初稿写得怎样。</li><li>编辑它。让它抓人眼球、有冲击力。</li><li>参考别人内容的<em>结构</em>，而不是想法，来增强你自己的内容。</li><li>根据互动反馈不断迭代。</li></ul><p>你不需要课程才能开始，但如果你想把所有策略都集中在一个地方，可以考虑加入10月28日开课的<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">作家训练营（Writer&#39;s Bootcamp）</a>。我们会讲解帖子、推文串、邮件通讯，以及其他写作策略，比如社交增长和受众建立。</p><p>大多数人在写短内容时遇到的问题是这样的：</p><p>他们不想显得浅显。</p><p>他们不想“玩身份地位的游戏”。</p><p>当人们不去关注或互动他们发的那些他们自认为聪明、酷炫、深刻的想法时，他们就会不高兴。</p><p>别再这样想了。</p><p>把它想成，你正在把人们的思维从浅显扩展到深刻。</p><p>如果你指望人们已经知道你所知道的一切，你要怎么帮助他们？</p><p>你是在人们所在的层次上与他们相遇，那大多数时候都会是浅显的层次（这也正是他们会出现在社交媒体上的原因），但接下来，你的职责就是在你的长内容里，把他们引向更深的东西。</p><p>你需要把你所有的内容都当作一个整体来思考。</p><p>你的帖子、推文串和邮件通讯，都是同一个有机体。</p><p>短内容用来吸引广泛且相对浅显的受众。</p><p>中等篇幅内容，比如推文串和较短的YouTube视频，是要往深一点走，让合适的人自己选择加入你的邮件列表、观看你的视频，或阅读你的书籍/指南/课程。</p><p>长内容，比如邮件通讯和长视频或播客，是为那些忠实粉丝准备的。他们与你的目标高度一致，想从你身上尽可能多地学习。</p><h3 id="_2-写中等篇幅内容来教育人们。" tabindex="-1">2）写中等篇幅内容来教育人们。 <a class="header-anchor" href="#_2-写中等篇幅内容来教育人们。" aria-label="Permalink to &quot;2）写中等篇幅内容来教育人们。&quot;">​</a></h3><p>在我看来，中等篇幅内容的作用是展示<em>能力</em>。</p><p>推文串、轮播图、短YouTube视频、长帖子、微文章，等等。</p><p>选一种适合的风格，然后不断打磨提升。</p><p>就我个人而言，我喜欢推文串，因为它们可以很容易地转发成轮播图，也能用作较短YouTube视频的脚本。</p><p>（我播放量最高、达150万次的YouTube视频，正是<a href="https://x.com/thedankoe/status/1603724124047769600" target="_blank" rel="noreferrer">这条推文串</a>的扩展版，而它本身又是这条<a href="https://x.com/thedankoe/status/1538861422779764738" target="_blank" rel="noreferrer">短内容帖子</a>的延伸。）</p><p>推文串、轮播图和短视频在以下几方面表现出色：</p><ul><li>建立权威和信任。</li><li>给人们提供足够的信息，让他们立刻关注你。</li><li>把大量的人引到推文串的末尾，那里你可以宣传你的邮件通讯、订阅入口，甚至产品。</li></ul><p>仅凭推文串，你就能建立起高质量的受众，但问题依然存在：</p><p>你的粉丝数量已经不再重要了。</p><h3 id="_3-写长内容来打造1000个真正的粉丝。" tabindex="-1">3）写长内容来打造1000个真正的粉丝。 <a class="header-anchor" href="#_3-写长内容来打造1000个真正的粉丝。" aria-label="Permalink to &quot;3）写长内容来打造1000个真正的粉丝。&quot;">​</a></h3><p>你所有的内容都应该引导人们沿着信任与价值的层级往上走。</p><p>帖子带来读者。</p><p>推文串带来粉丝。</p><p>邮件通讯带来超级粉丝。</p><p>如果你熟悉<em>1000个真正的粉丝</em>这个概念，那么一份高互动度的邮件列表，就足以让你受用一生。</p><p>我第一次接触到这种力量,是在读Ryan Deiss的《The Invisible Selling Machine》(《隐形销售机器》)时。这是我真正读过的少数几本商业书籍之一。我的商业建议大多来自古代哲学和现代心理学。</p><p>虽然我现在已经不再使用他的任何策略了,但这本书的第一条经验教训,一直留在我心里。</p><p>Ryan当时正处于混乱之中。那种你必须迅速搞到一大笔钱,否则就完蛋的人生境况。于是,他创建了一个有价值的优惠方案,发给了他的邮件列表,一夜之间赚到了一笔可观的钱(因为他花时间建立了一个邮件列表)。</p><p>我现在手边没有这本书,但那笔钱多得让人不知道该怎么用。如果我记得没错的话,远超过10万美元(别拿这个数字来引用我)。</p><p>简而言之,新闻通讯是那些真正关心你、关心你的兴趣的人前去支持你的地方。</p><p>如果你想学习我如何写新闻通讯和YouTube脚本,我们将在<a href="https://community.kortex.co/c/live-events/how-dan-writes-newsletters-youtube-scripts" target="_blank" rel="noreferrer">Kortex YT频道的直播</a>中讲解。时间是10月25日,美国山地时间(MST)下午1点。</p><h2 id="_2025年-聪明的创作者将如何打造受众" tabindex="-1">2025年,聪明的创作者将如何打造受众 <a class="header-anchor" href="#_2025年-聪明的创作者将如何打造受众" aria-label="Permalink to &quot;2025年,聪明的创作者将如何打造受众&quot;">​</a></h2><p>打造受众归结为六件事:</p><ul><li>在社交媒体上测试想法和结构。</li><li>拥有一个新帖子的催化剂策略。</li><li>把最好的想法变成推文串和新闻通讯。</li><li>把你的写作内容改编到其他平台上。</li><li>利用指数级事件。</li><li>把所有人引导到你的新闻通讯上。</li></ul><p>这些就是你每天早上唯一需要专注的事情。</p><p>做得好的话,这应该每天不超过1-2个小时。</p><h3 id="_1-社交媒体帖子就是新的mvp" tabindex="-1">1)社交媒体帖子就是新的MVP <a class="header-anchor" href="#_1-社交媒体帖子就是新的mvp" aria-label="Permalink to &quot;1)社交媒体帖子就是新的MVP&quot;">​</a></h3><p>MVP=最小可行产品(minimum viable product)。</p><p>在我看来,社交媒体是一个测试场,用来测试那些可以分发到更高杠杆平台上的想法。</p><p>在社交媒体上发帖。</p><p>把你最好的帖子变成推文串和新闻通讯。</p><p>把你最好的推文串和新闻通讯变成免费下载资源。</p><p>把免费下载资源变成一个信息产品或服务。</p><p>把你的信息产品或服务变成软件、实体产品、书籍,或其他可规模化的业务。</p><h3 id="_2-你需要一个想法催化剂" tabindex="-1">2)你需要一个想法催化剂 <a class="header-anchor" href="#_2-你需要一个想法催化剂" aria-label="Permalink to &quot;2)你需要一个想法催化剂&quot;">​</a></h3><p>如果你的粉丝很少或为零,你会经历新手地狱。</p><p>我不知道人们刚开始时脑子里在想什么,但不,算法不会对你的帖子做任何事。你可能会走运,但我不喜欢把我一生的事业寄托在运气上。</p><p>你需要一种方法来保证人们看到你的帖子。这样,你才能真正看清哪些想法效果好,哪些不好。</p><p>换句话说,你需要一个<em>拥有受众的人</em>来点赞、评论或分享你的帖子。评论目前似乎是最有效的方式(取决于平台)。</p><p>有几种方法可以做到这一点:</p><p><strong>1)付费玩法</strong></p><p>广告让你可以付钱给一个平台(比如Facebook或Google),让它把你的帖子展示给更多的受众。</p><p>但广告并不是接触更大受众的唯一方式。事实上,我更愿意不把钱付给平台。我更愿意付钱给一个我想与之建立关系、并拥有高度活跃受众的个人。</p><p>几乎每个拥有社交媒体受众的人,也都有一项帮你增长的服务。这对他们来说是轻松赚钱,对你来说也大有好处。</p><p>给粉丝超过2万的账号发私信,问他们是否能帮忙启动社交增长。</p><p>(大品牌为此收费数千美元,因为其他品牌把它视为一种可行的营销策略。如果你没有几千美元,就不要去联系大品牌求增长。)</p><p>如果你不想在增长上投资,(1)没关系,但(2)我会质疑你对打造自己一生的事业是否认真。你会花40美元吃一顿愉快的晚餐,但如果你有产品并理解投资回报率(ROI)的概念,你却不愿意在能让你赚回10倍的商业流量上花同样多的钱。</p><p>还有,不。我不同意那些认为在业务增长上投钱是“不真诚”的人,他们这么说只是为了向你推销<em>他们自己的</em>增长方式。再说一次,不,你不需要像其他人一样在评论区里拼命内卷,参与那场逐底竞赛(这不代表你不能评论、不能交朋友)。</p><p><strong>2)建立一个部落</strong></p><p>现在,你不<em>需要</em>付费才能玩社交媒体这个游戏。</p><p>我已经三年没这么做了。但你可以肯定,当我刚开始时,我会竭尽全力去改变我当时的生活状况。我太想摆脱自由职业了。我不会因为那些增长大师说这样不好——却给不出一个合乎逻辑的理由——而拖延这件事。</p><p>还有其他方法可以让你的帖子传播到更大的受众群体中。</p><p>你把自己嵌入社交媒体上的一个部落中。</p><ul><li>找到跟你规模相近的账号。</li><li>把他们加入一个列表,或收藏他们的主页。</li><li>每天回复他们的内容。</li></ul><p>然后,把一段对话从评论区转到私信里。</p><p>把它当作你在给朋友发消息一样对待——就像你发现了一件有趣的事,想分享给他们。</p><p>之后,问问他们在做什么来实现增长。</p><p>搞定,现在你就处在一个可以提出建议的位置——问对方要不要通过互相为对方的内容互动来一起增长。</p><p>如果你想亲眼看到这一切发生,明年某个时候,出于与Kortex相关的原因,我可能会把自己嵌入X上的创业细分领域。欢迎观看。</p><p><strong>3)价值交换</strong></p><p>如果你没钱,或者不擅长交朋友,也许你拥有某种技能,或其他形式的社会资本,可以用来交换分享。</p><p>比如,你拥有Instagram的受众,而他们拥有X的受众。</p><p>你可以提出在IG上分享他们的帖子,而他们在X上分享你的。</p><p>或者,也许你可以帮他们搭建一个落地页,或写一套邮件序列,以此交换分享。</p><p>在这方面尽情发挥你的创意吧。</p><p>交换商品和服务,与交换金钱一样可行。</p><h3 id="_3-把你最好的帖子变成新闻通讯" tabindex="-1">3)把你最好的帖子变成新闻通讯 <a class="header-anchor" href="#_3-把你最好的帖子变成新闻通讯" aria-label="Permalink to &quot;3)把你最好的帖子变成新闻通讯&quot;">​</a></h3><p>当一篇帖子表现异常出色时,就把它变成一封新闻通讯。</p><p>使用BPAS框架。</p><ul><li>大想法(Big idea)——在帖子中陈述这个想法。</li><li>问题(Problem)——基于这个大想法,描绘一个让人有共鸣的问题。</li><li>放大(Amplify)——举例说明这个问题如何影响人们的生活。</li><li>解决方案(Solution)——给出能帮助解决这个问题的步骤、经验或洞见。</li></ul><p>这就是写一封新闻通讯的简洁方法。</p><p>只有两个部分。开头部分包含大想法、问题以及对问题的放大,然后是解决方案部分,你在其中列出每一个步骤,并为每一步给出背景说明(就像我在这封信里所做的那样)。</p><h3 id="_4-利用指数级事件" tabindex="-1">4)利用指数级事件 <a class="header-anchor" href="#_4-利用指数级事件" aria-label="Permalink to &quot;4)利用指数级事件&quot;">​</a></h3><p>受众增长是非线性的。</p><p>你会有一段时间停滞不前,或进展缓慢。然后,你会突然看到大量增长。</p><p>在X上,有那么几篇帖子为我带来了远超平均水平的受众增长。每次我重发那些想法时,我都知道我会获得新粉丝。</p><p>我的YouTube增长曾经非常缓慢,直到有一个视频表现极其出色(一个月内为我增加了20万订阅者)。</p><p>我的IG增长也很缓慢,但当我用某些reels或轮播图中了大奖时,几个月内我涨了120万粉丝。</p><p>大部分爆火式增长,来自你花上一到两年时间不断试验各种想法,直到遇到这样一个指数级事件。</p><p>当你有一个表现良好的话题时,别犯傻去尝试别的东西。就那个主题,从各个角度尽人力所能及地多发内容,直到增长开始趋于平缓。</p><p>我又制作了20多个关于一人企业模式的视频,正是它们把我带到了今天的位置。</p><p>这与死守一个细分领域关系不大,更多是关于试验你的兴趣,并在那些奏效的想法上加倍投入。</p><p>我有很多关于哲学和生产力的视频,表现比我的一人企业视频还好。我也在那些上面加倍投入了。</p><h3 id="_5-把所有人都引导到你的新闻通讯上" tabindex="-1">5)把所有人都引导到你的新闻通讯上 <a class="header-anchor" href="#_5-把所有人都引导到你的新闻通讯上" aria-label="Permalink to &quot;5)把所有人都引导到你的新闻通讯上&quot;">​</a></h3><p>在任何地方推广你的新闻通讯。</p><p>每天在你的帖子下面或你的Story里推广一次。</p><p>在你的推文串或轮播图结尾处推广。</p><p>在你的YouTube视频简介里推广。</p><p>你的新闻通讯,将是你推广你的产品或服务的地方(大多数时候,不是所有时候)。</p><p>如果你不能让人加入你的新闻通讯,你可能再也见不到他们了。</p><p>记住,粉丝数不重要。邮件列表才重要。</p><p>这封信就到这里。</p><p>希望对你有帮助。</p><p>——Dan</p><hr><p><a href="/en/letters/the-future-of-creators-how-to-build-an-audience-in-2025">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',196))])}const g=l(d,[["render",c]]);export{T as __pageData,g as default};
